insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-adult-ed-program-joins-credential-by-name-2026-11-25','decision','An adult school program joins a credential by its own name or stated credential, never its CIP title','Adult Education CPL Starting Points, 2026-11-25: matching on the CIP title pulled CPR classes into EMT and class fragments (Alzheimer''s Basic Plus) into CNA. Programs now join by program name or the credential they name, with per-family patterns and exclusions (build_data.py F and EXCL); 1,002 of 1,733 school-delivered programs match 33 credentials.',array['adult-education','caep','quick-adopt','matching'],'proposed','Session with Sam, 2026-11-25','Claude (adult ed side job, 2026-11-25)',null,'Claude (adult ed side job, 2026-11-25)',date '2026-11-25'),
('d-quick-adopt-exhibit-credits-the-credential-2026-11-25','decision','A Quick Adopt exhibit offered for a credential must credit the credential itself','Adult Education CPL Starting Points, 2026-11-25: of 125 verified exhibits behind the credential families, 22 were dropped with a reason each (build_data.py DROP): college courses given by exam (Chaffey''s vocational nursing course under CNA), high school program exhibits, and a different credential filed under the family (EMR, BLS under EMT).',array['adult-education','quick-adopt','exhibits'],'proposed','Session with Sam, 2026-11-25','Claude (adult ed side job, 2026-11-25)',null,'Claude (adult ed side job, 2026-11-25)',date '2026-11-25'),
('d-could-adopt-reads-prescriptive-2026-11-25','decision','Could adopt reads the prescriptive M-ID list, never the CER''s potential_colleges','Adult Education CPL Starting Points, 2026-11-25, re-applying methodology-a-fold-carries-the-folded-tabs-rulings: could adopt comes from statewide_prescriptive.js (M-ID adoption_leverage, over-merged held, with the likely local course). The CER''s potential_colleges lacks the hold; switching cut 478 pairs to 261 and removed the CDA (75), ServSafe (22) and most BLS (37 of 42) lists.',array['adult-education','quick-adopt','m-id','eacr'],'proposed','Session with Sam, 2026-11-25','Claude (adult ed side job, 2026-11-25)',null,'Claude (adult ed side job, 2026-11-25)',date '2026-11-25'),
('r-get-credit-at-sam-2026-11-25','decision','Colleges that already credit a credential are labeled Get credit at','Sam, 2026-11-25, in session: "maybe Get Credit instead of Give credit, right? because you might send your alvord student to Pierce to get credit." The label speaks to the learner; each college carries a Send a student link to its MAP CPL landing page (cpldashboardcccco.azurewebsites.net/<slug>).',array['adult-education','quick-adopt','wording'],'verified','Sam in session, 2026-11-25','Sam',now(),'Claude (adult ed side job, 2026-11-25)',date '2026-11-25'),
('r-public-tools-take-the-catalog-look-sam-2026-11-25','decision','Public tools take the Credential Catalog''s look','Sam, 2026-11-25, in session: "format like the credential catalog style, which is the style we use for most public tools like this." The Catalog (library/adopt): its tokens, the public header with logo and Light or Dark, gold-edged figure tiles, rounded cards and lists, zebra tables and the footer.',array['design','public','library'],'verified','Sam in session, 2026-11-25','Sam',now(),'Claude (adult ed side job, 2026-11-25)',date '2026-11-25'),
('f-ca-map-initiative-college-in-public-exhibits-2026-11-25','fact','MAP''s sandbox CA MAP INITIATIVE COLLEGE shows as an articulating college on two public exhibits','2026-11-25: MAP''s public collaborative-exhibits API lists CA MAP INITIATIVE COLLEGE (slug CAMAP) on MAPICI-CRES1-1-001 CA Real Estate Salesperson (RLE 81, Articulated) and MAPICI-DRES-1-001 DRE Real Estate Salesperson License v2 (RLE 80, In Progress). A sandbox org (map_college_roster_rules.json). Sam: it should not be in the MAP Custom Reports dataset either; he will ask Pedro to exclude it.',array['map-data','sandbox','data-quality'],'proposed','Session with Sam, 2026-11-25','Claude (adult ed side job, 2026-11-25)',null,'Claude (adult ed side job, 2026-11-25)',date '2026-11-25')
on conflict (slug) do nothing;

